def solve_sudoku(grid):
    g = [row[:] for row in grid]
    rows = [set() for _ in range(9)]
    cols = [set() for _ in range(9)]
    boxes = [set() for _ in range(9)]
    empty = []
    for r in range(9):
        for c in range(9):
            v = g[r][c]
            if v:
                rows[r].add(v); cols[c].add(v); boxes[r // 3 * 3 + c // 3].add(v)
            else:
                empty.append((r, c))

    def search():
        if not empty:
            return True
        best_i, best_opts = None, None
        for i, (r, c) in enumerate(empty):
            opts = [v for v in range(1, 10)
                    if v not in rows[r] and v not in cols[c] and v not in boxes[r // 3 * 3 + c // 3]]
            if best_opts is None or len(opts) < len(best_opts):
                best_i, best_opts = i, opts
                if len(opts) <= 1:
                    break
        r, c = empty.pop(best_i)
        b = r // 3 * 3 + c // 3
        for v in best_opts:
            g[r][c] = v
            rows[r].add(v); cols[c].add(v); boxes[b].add(v)
            if search():
                return True
            rows[r].discard(v); cols[c].discard(v); boxes[b].discard(v)
        g[r][c] = 0
        empty.insert(best_i, (r, c))
        return False

    search()
    return g

def parse_json(text):
    i = 0
    n = len(text)

    def ws():
        nonlocal i
        while i < n and text[i] in " \t\n\r":
            i += 1

    def err(msg="invalid JSON"):
        raise ValueError(f"{msg} at {i}")

    def value():
        nonlocal i
        ws()
        if i >= n:
            err()
        ch = text[i]
        if ch == "{":
            return obj()
        if ch == "[":
            return arr()
        if ch == '"':
            return string()
        for lit, val in (("true", True), ("false", False), ("null", None)):
            if text.startswith(lit, i):
                i += len(lit)
                return val
        if ch == "-" or ch.isdigit():
            return number()
        err()

    def obj():
        nonlocal i
        i += 1
        out = {}
        ws()
        if i < n and text[i] == "}":
            i += 1
            return out
        while True:
            ws()
            if i >= n or text[i] != '"':
                err("expected key")
            k = string()
            ws()
            if i >= n or text[i] != ":":
                err("expected :")
            i += 1
            out[k] = value()
            ws()
            if i < n and text[i] == ",":
                i += 1
                continue
            if i < n and text[i] == "}":
                i += 1
                return out
            err()

    def arr():
        nonlocal i
        i += 1
        out = []
        ws()
        if i < n and text[i] == "]":
            i += 1
            return out
        while True:
            out.append(value())
            ws()
            if i < n and text[i] == ",":
                i += 1
                continue
            if i < n and text[i] == "]":
                i += 1
                return out
            err()

    def string():
        nonlocal i
        i += 1
        buf = []
        esc = {'"': '"', "\\": "\\", "/": "/", "b": "\b", "f": "\f", "n": "\n", "r": "\r", "t": "\t"}
        while True:
            if i >= n:
                err("unterminated string")
            ch = text[i]
            if ch == '"':
                i += 1
                return "".join(buf)
            if ch == "\\":
                i += 1
                if i >= n:
                    err()
                e = text[i]
                if e in esc:
                    buf.append(esc[e]); i += 1
                elif e == "u":
                    h = text[i + 1:i + 5]
                    if len(h) != 4 or any(c not in "0123456789abcdefABCDEF" for c in h):
                        err("bad unicode escape")
                    buf.append(chr(int(h, 16))); i += 5
                else:
                    err("bad escape")
            elif ord(ch) < 0x20:
                err("control character")
            else:
                buf.append(ch); i += 1

    def number():
        nonlocal i
        start = i
        if text[i] == "-":
            i += 1
        if i >= n or not text[i].isdigit():
            err()
        if text[i] == "0":
            i += 1
            if i < n and text[i].isdigit():
                err("leading zero")
        else:
            while i < n and text[i].isdigit():
                i += 1
        is_float = False
        if i < n and text[i] == ".":
            is_float = True
            i += 1
            if i >= n or not text[i].isdigit():
                err()
            while i < n and text[i].isdigit():
                i += 1
        if i < n and text[i] in "eE":
            is_float = True
            i += 1
            if i < n and text[i] in "+-":
                i += 1
            if i >= n or not text[i].isdigit():
                err()
            while i < n and text[i].isdigit():
                i += 1
        s = text[start:i]
        return float(s) if is_float else int(s)

    v = value()
    ws()
    if i != n:
        err("trailing characters")
    return v

def count_n_queens(n):
    full = (1 << n) - 1

    def go(cols, d1, d2):
        if cols == full:
            return 1
        total = 0
        free = full & ~(cols | d1 | d2)
        while free:
            bit = free & -free
            free ^= bit
            total += go(cols | bit, ((d1 | bit) << 1) & full, (d2 | bit) >> 1)
        return total

    return go(0, 0, 0) if n > 0 else 1

def wildcard_match(s, p):
    i = j = 0
    star = -1
    mark = 0
    while i < len(s):
        if j < len(p) and (p[j] == "?" or p[j] == s[i]):
            i += 1; j += 1
        elif j < len(p) and p[j] == "*":
            star, mark = j, i
            j += 1
        elif star != -1:
            j = star + 1
            mark += 1
            i = mark
        else:
            return False
    while j < len(p) and p[j] == "*":
        j += 1
    return j == len(p)

import datetime as dt

def business_days(start, end, holidays):
    a, b = dt.date.fromisoformat(start), dt.date.fromisoformat(end)
    if b < a:
        return -business_days(end, start, holidays)
    days = (b - a).days
    full, rem = divmod(days, 7)
    count = full * 5
    for k in range(rem):
        if (a + dt.timedelta(days=full * 7 + k)).weekday() < 5:
            count += 1
    for h in set(holidays):
        d = dt.date.fromisoformat(h)
        if a <= d < b and d.weekday() < 5:
            count -= 1
    return count

def num_decodings(s):
    M = 10**9 + 7

    def one(c):
        return 9 if c == "*" else (0 if c == "0" else 1)

    def two(a, b):
        if a == "*":
            if b == "*":
                return 15
            return 2 if b <= "6" else 1
        if a == "1":
            return 9 if b == "*" else 1
        if a == "2":
            return 6 if b == "*" else (1 if b <= "6" else 0)
        return 0

    prev2, prev1 = 1, one(s[0]) if s else 1
    for i in range(1, len(s)):
        cur = (one(s[i]) * prev1 + two(s[i - 1], s[i]) * prev2) % M
        prev2, prev1 = prev1, cur
    return prev1 % M

import heapq

def alien_order(words):
    letters = {c for w in words for c in w}
    adj = {c: set() for c in letters}
    indeg = {c: 0 for c in letters}
    for a, b in zip(words, words[1:]):
        for x, y in zip(a, b):
            if x != y:
                if y not in adj[x]:
                    adj[x].add(y)
                    indeg[y] += 1
                break
        else:
            if len(a) > len(b):
                return ""
    heap = [c for c in letters if indeg[c] == 0]
    heapq.heapify(heap)
    out = []
    while heap:
        c = heapq.heappop(heap)
        out.append(c)
        for d in adj[c]:
            indeg[d] -= 1
            if indeg[d] == 0:
                heapq.heappush(heap, d)
    return "".join(out) if len(out) == len(letters) else ""

def kth_smallest_distance(nums, k):
    a = sorted(nums)
    n = len(a)

    def count(d):
        c = left = 0
        for right in range(n):
            while a[right] - a[left] > d:
                left += 1
            c += right - left
        return c

    lo, hi = 0, a[-1] - a[0]
    while lo < hi:
        mid = (lo + hi) // 2
        if count(mid) >= k:
            hi = mid
        else:
            lo = mid + 1
    return lo

def islands_after_adds(rows, cols, positions):
    parent = {}

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    out, count = [], 0
    for r, c in positions:
        key = r * cols + c
        if key in parent:
            out.append(count)
            continue
        parent[key] = key
        count += 1
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols:
                nk = nr * cols + nc
                if nk in parent:
                    a, b = find(key), find(nk)
                    if a != b:
                        parent[a] = b
                        count -= 1
        out.append(count)
    return out

def words_to_number(text):
    units = {w: i for i, w in enumerate(
        "zero one two three four five six seven eight nine ten eleven twelve thirteen fourteen fifteen "
        "sixteen seventeen eighteen nineteen".split())}
    tens = {w: 10 * i for i, w in enumerate("twenty thirty forty fifty sixty seventy eighty ninety".split(), 2)}
    scales = {"thousand": 10**3, "million": 10**6, "billion": 10**9}
    words = text.replace("-", " ").split()
    sign = 1
    if words and words[0] == "minus":
        sign, words = -1, words[1:]
    total = cur = 0
    for w in words:
        if w == "and":
            continue
        if w in units:
            cur += units[w]
        elif w in tens:
            cur += tens[w]
        elif w == "hundred":
            cur *= 100
        elif w in scales:
            total += cur * scales[w]
            cur = 0
        else:
            raise ValueError(w)
    return sign * (total + cur)

