import re

def eval_bool(expr, env):
    toks = re.findall(r"\(|\)|[A-Za-z_][A-Za-z0-9_]*", expr)
    pos = 0

    def peek():
        return toks[pos] if pos < len(toks) else None

    def take():
        nonlocal pos
        pos += 1
        return toks[pos - 1]

    def or_():
        v = and_()
        while peek() == "or":
            take()
            r = and_()
            v = v or r
        return v

    def and_():
        v = not_()
        while peek() == "and":
            take()
            r = not_()
            v = v and r
        return v

    def not_():
        if peek() == "not":
            take()
            return not not_()
        return atom()

    def atom():
        t = take()
        if t == "(":
            v = or_()
            take()
            return v
        if t == "true":
            return True
        if t == "false":
            return False
        return bool(env[t])

    return or_()

def longest_palindrome(s):
    if not s:
        return ""
    t = "^#" + "#".join(s) + "#$"
    p = [0] * len(t)
    center = right = 0
    for i in range(1, len(t) - 1):
        if i < right:
            p[i] = min(right - i, p[2 * center - i])
        while t[i + p[i] + 1] == t[i - p[i] - 1]:
            p[i] += 1
        if i + p[i] > right:
            center, right = i, i + p[i]
    best_len, best_c = 0, 0
    for i, v in enumerate(p):
        if v > best_len:
            best_len, best_c = v, i
    start = (best_c - best_len) // 2
    return s[start:start + best_len]
